GENESIS_NOTES[6]={"summary":"O capítulo relata a multiplicação dos seres humanos, a menção aos filhos de Deus, às filhas dos seres humanos e aos nefilins. O texto descreve a maldade, a corrupção e a violência na terra. Deus anuncia que eliminará os seres vivos da terra, mas Noé encontra favor diante de YHWH. Noé é apresentado como justo e íntegro entre os de sua geração e como alguém que andava com Deus. Deus lhe ordena construir uma arca, fornece suas medidas e instruções, anuncia o dilúvio e estabelece uma aliança com ele.","explanation":"O capítulo começa com referências aos filhos de Deus, às filhas dos seres humanos e aos nefilins, sem explicar detalhadamente a identidade desses grupos. Em seguida, o narrador descreve a avaliação divina sobre a maldade humana e a condição da terra, caracterizada por corrupção e violência. Noé é destacado no relato. A partir de 6:13, o texto registra as instruções para a construção da arca: material, compartimentos, revestimento, medidas, abertura, porta e andares. Também apresenta quem entraria na arca e a provisão de alimento. O capítulo termina afirmando que Noé fez conforme tudo o que Deus lhe ordenou.","episodes":"1. Multiplicação dos seres humanos e nascimento de filhas (6:1)\n2. Os filhos de Deus tomam mulheres entre as filhas dos seres humanos (6:2-4)\n3. A avaliação de YHWH sobre a maldade humana (6:5-7)\n4. Noé encontra favor diante de YHWH (6:8)\n5. Noé é apresentado e seus três filhos são nomeados (6:9-10)\n6. Corrupção e violência na terra (6:11-12)\n7. Anúncio do fim de toda carne e instruções para a arca (6:13-16)\n8. Anúncio do dilúvio e estabelecimento da aliança (6:17-18)\n9. Entrada dos animais e armazenamento de alimento (6:19-21)\n10. Noé faz conforme a ordem recebida (6:22)","refs":"Gn 5:28-32; Gn 6:1-22; Gn 7:1-5; Mt 24:37-39; Lc 17:26-27; Hb 11:7; 1Pe 3:20; 2Pe 2:5","characters":[["YHWH / Deus","Fala sobre a permanência de seu espírito no ser humano, avalia a maldade da humanidade, anuncia o dilúvio e dá instruções a Noé. (Gn 6:3, 5-7, 13-21)"],["Filhos de Deus","Grupo mencionado no relato que vê as filhas dos seres humanos e toma mulheres dentre elas. O capítulo não detalha sua identidade. (Gn 6:2, 4)"],["Filhas dos seres humanos","Mulheres vistas pelos filhos de Deus, que as tomam como mulheres. (Gn 6:1-2, 4)"],["Nefilins","São mencionados como presentes na terra naqueles dias e também depois; o texto os associa aos valentes da antiguidade, homens de renome. (Gn 6:4)"],["Noé","Encontra favor diante de YHWH, é descrito como justo e íntegro entre os de sua geração, recebe as instruções da arca e as cumpre. (Gn 6:8-22)"],["Sem","Um dos três filhos de Noé. (Gn 6:10, 18)"],["Cam","Um dos três filhos de Noé. (Gn 6:10, 18)"],["Jafé","Um dos três filhos de Noé. (Gn 6:10, 18)"],["Humanidade","É descrita como multiplicada na terra, marcada pela maldade e pela corrupção de seu caminho. (Gn 6:1-7, 11-13)"]],"symbols":[["Filhos de Deus e filhas dos seres humanos","Expressões usadas pelo texto para identificar os grupos mencionados no início do capítulo; suas identidades não são explicadas ali. (Gn 6:1-4)"],["Nefilins","Nome atribuído a seres mencionados na terra naquele período; o texto também os relaciona aos valentes da antiguidade e homens de renome. (Gn 6:4)"],["Cento e vinte anos","Período mencionado na declaração de YHWH sobre os dias do ser humano. (Gn 6:3)"],["Coração e pensamentos","Linguagem usada para descrever a inclinação dos pensamentos humanos como continuamente má. (Gn 6:5)"],["Corrupção","Condição atribuída à terra e ao caminho de toda a humanidade. (Gn 6:11-12)"],["Violência","Característica destacada como presente e abundante na terra. (Gn 6:11, 13)"],["Favor diante de YHWH","Expressão usada para descrever a condição de Noé diante de YHWH. (Gn 6:8)"],["Arca","Construção ordenada a Noé para preservar sua família e representantes dos seres vivos durante o dilúvio. (Gn 6:14-21)"],["Madeira de gofer","Material indicado para a construção da arca. (Gn 6:14)"],["Betume","Material indicado para revestir a arca por dentro e por fora. (Gn 6:14)"],["Abertura e porta lateral","Elementos estruturais especificados nas instruções para a arca. (Gn 6:16)"],["Três andares","Organização interna indicada para a arca: inferior, segundo e terceiro. (Gn 6:16)"],["Dilúvio de águas","Evento anunciado por Deus para destruir toda carne em que há fôlego de vida debaixo dos céus. (Gn 6:17)"],["Aliança","Compromisso anunciado por Deus a Noé, que entraria na arca com sua família. (Gn 6:18)"],["Macho e fêmea","Distinção indicada para os pares de seres vivos que seriam conservados na arca. (Gn 6:19-20)"],["Alimento armazenado","Provisão que Noé deveria reunir para si e para os animais. (Gn 6:21)"]]};
GENESIS_NOTES[7]={"summary":"YHWH ordena que Noé entre na arca com sua família e leve consigo os animais, distinguindo os animais puros dos que não eram puros e indicando também os pares de aves. Após sete dias, começa o dilúvio. O texto informa a idade de Noé, a data do início das águas, a chuva de quarenta dias e quarenta noites, a abertura das fontes do grande abismo e das comportas dos céus. As águas cobrem as montanhas, os seres vivos que estavam fora da arca morrem, e Noé permanece na arca com os que entraram com ele. O capítulo termina informando que as águas prevaleceram por cento e cinquenta dias.","explanation":"O capítulo dá continuidade às instruções de Gênesis 6 e narra sua execução. São mencionados sete pares de animais puros, um par dos animais que não eram puros e sete pares de aves. A entrada na arca ocorre antes do início das águas; o texto menciona um intervalo de sete dias. A data é situada no ano seiscentos da vida de Noé, no segundo mês, dia dezessete. A narrativa descreve duas origens das águas: as fontes do grande abismo e as comportas dos céus. A chuva dura quarenta dias e quarenta noites. O relato enfatiza a elevação das águas, a cobertura das montanhas e a morte dos seres que estavam fora da arca. Noé, sua família e os seres vivos que estavam com eles permanecem dentro da arca.","episodes":"1. Ordem para Noé entrar na arca com sua casa (7:1)\n2. Instruções sobre os animais puros, os que não eram puros e as aves (7:2-3)\n3. Anúncio da chuva após sete dias (7:4)\n4. Noé cumpre a ordem de YHWH (7:5)\n5. Noé, aos seiscentos anos, entra na arca com sua família (7:6-9)\n6. Início do dilúvio após sete dias (7:10)\n7. Data do início do dilúvio e abertura das fontes e comportas dos céus (7:11-12)\n8. Entrada de Noé, sua família e os animais na arca (7:13-16)\n9. A arca é levantada pelas águas e as montanhas ficam cobertas (7:17-20)\n10. Morte dos seres vivos que estavam fora da arca (7:21-23)\n11. As águas prevalecem durante cento e cinquenta dias (7:24)","refs":"Gn 6:13-22; Gn 7:1-24; Gn 8:1-5; Mt 24:37-39; Lc 17:26-27; Hb 11:7; 1Pe 3:20; 2Pe 2:5","characters":[["YHWH","Ordena a entrada de Noé na arca, anuncia a chuva e fecha a porta da arca. (Gn 7:1-4, 16)"],["Noé","Entra na arca com sua família e os animais, seguindo as instruções recebidas. (Gn 7:1-16)"],["Sem","Filho de Noé; entra na arca com sua mulher. (Gn 7:7, 13)"],["Cam","Filho de Noé; entra na arca com sua mulher. (Gn 7:7, 13)"],["Jafé","Filho de Noé; entra na arca com sua mulher. (Gn 7:7, 13)"],["Mulher de Noé","Entra na arca com Noé. (Gn 7:7, 13)"],["Mulheres dos filhos de Noé","As três mulheres dos filhos de Noé entram na arca com eles. (Gn 7:7, 13)"],["Seres humanos e animais","Os seres vivos que estavam fora da arca são atingidos pelas águas; os que entraram com Noé permanecem na arca. (Gn 7:14-23)"]],"symbols":[["Arca","Embarcação na qual Noé, sua família e os animais entram e permanecem durante o dilúvio. (Gn 7:1, 7-9, 13-18)"],["Animais puros","Categoria de animais para os quais são indicados sete pares, macho e fêmea. (Gn 7:2, 8)"],["Animais que não eram puros","Categoria de animais para os quais é indicado um par, macho e fêmea. (Gn 7:2, 8)"],["Aves dos céus","As aves são mencionadas com sete pares para conservar sua descendência sobre a terra. (Gn 7:3, 14)"],["Sete dias","Intervalo anunciado antes de as águas do dilúvio virem sobre a terra. (Gn 7:4, 10)"],["Quarenta dias e quarenta noites","Duração da chuva sobre a terra. (Gn 7:4, 12)"],["Seiscentos anos de Noé","Idade de Noé quando veio o dilúvio de águas. (Gn 7:6, 11)"],["Segundo mês, dia dezessete","Data indicada para o início do dilúvio no relato. (Gn 7:11)"],["Fontes do grande abismo","Fontes que se rompem no dia em que começa o dilúvio. (Gn 7:11)"],["Comportas dos céus","Aberturas dos céus mencionadas junto ao rompimento das fontes do grande abismo. (Gn 7:11)"],["Porta da arca","O texto declara que YHWH fechou a porta atrás de Noé. (Gn 7:16)"],["Montanhas cobertas","As altas montanhas debaixo dos céus ficam cobertas pelas águas. (Gn 7:19-20)"],["Fôlego de vida","Expressão usada para descrever os seres que morreram nas águas quando estavam fora da arca. (Gn 7:21-22)"],["Cento e cinquenta dias","Período durante o qual as águas prevaleceram sobre a terra. (Gn 7:24)"]]};
GENESIS_NOTES[10]={"summary":"Gênesis 10 apresenta a descendência dos filhos de Noé — Jafé, Cam e Sem — e relaciona seus descendentes, clãs, línguas, territórios e nações. O capítulo menciona a expansão das populações pelas terras e destaca Ninrode, associado ao início de um reino cuja primeira referência é Babel, na terra de Sinear. Também registra a linhagem de Canaã e a descendência de Héber, incluindo a observação sobre Pelegue e a divisão da terra.","explanation":"O capítulo está organizado em três seções genealógicas: os descendentes de Jafé (10:2-5), os descendentes de Cam (10:6-20) e os descendentes de Sem (10:21-31). As listas relacionam famílias, línguas, terras e nações depois do dilúvio. Na seção de Cam, o texto destaca Ninrode e cidades associadas ao início de seu reino, além de povos ligados a Mizraim e Canaã. Na seção de Sem, aparecem Héber, Pelegue e Joctã e seus descendentes. O texto não fornece explicações adicionais para todos os nomes e localidades.","episodes":"1. Introdução aos filhos de Noé e seus descendentes (10:1)\n2. Descendentes de Jafé (10:2-5)\n3. Descendentes de Cam (10:6-7)\n4. Ninrode e sua descrição (10:8-9)\n5. Cidades do princípio do reino de Ninrode (10:10-12)\n6. Descendentes de Mizraim (10:13-14)\n7. Descendentes de Canaã e seus territórios (10:15-19)\n8. Resumo dos descendentes de Cam (10:20)\n9. Introdução aos descendentes de Sem (10:21)\n10. Filhos de Sem e descendentes de Arã (10:22-23)\n11. Linha de Arfaxade, Selá e Héber (10:24)\n12. Pelegue e Joctã (10:25)\n13. Descendentes de Joctã e região de habitação (10:26-30)\n14. Resumo dos descendentes de Sem e conclusão (10:31-32)","refs":"Gn 5:32; Gn 9:18-19; Gn 10:1-32; Gn 11:1-9, 10-32; 1Cr 1:5-23; Lc 3:34-36","characters":[["Noé","Pai de Sem, Cam e Jafé; seus descendentes são apresentados como origem das famílias e nações mencionadas depois do dilúvio. (Gn 9:18-19; 10:1)"],["Jafé","Um dos filhos de Noé. Seus descendentes relacionados incluem Gômer, Magogue, Madai, Javã, Tubal, Meseque e Tirás. (Gn 10:1-5)"],["Cam","Um dos filhos de Noé. Seus filhos nomeados são Cuxe, Mizraim, Pute e Canaã. (Gn 10:1, 6-20)"],["Sem","Um dos filhos de Noé, identificado como pai de todos os filhos de Héber e irmão mais velho de Jafé. (Gn 10:1, 21-31)"],["Ninrode","Descendente de Cuxe, descrito como poderoso na terra e poderoso caçador diante de YHWH. O texto relaciona a ele o princípio de um reino. (Gn 10:8-12)"],["Cuxe","Filho de Cam e pai de vários descendentes, entre eles Ninrode e os filhos de Raamá. (Gn 10:6-8)"],["Mizraim","Filho de Cam; seus descendentes são associados aos luditas, anamitas, leabitas, naftuítas, patrusitas, casluítas e caftoritas. (Gn 10:6, 13-14)"],["Canaã","Filho de Cam; seus descendentes incluem Sidom, Hete e diversos povos cananeus. (Gn 10:6, 15-19)"],["Raamá","Descendente de Cuxe e pai de Sabá e Dedã. (Gn 10:7)"],["Héber","Descendente de Sem, por meio de Arfaxade e Selá; pai de Pelegue e Joctã. (Gn 10:24-25)"],["Pelegue","Filho de Héber; o texto relaciona seu nome ao fato de que, em seus dias, a terra foi dividida. (Gn 10:25)"],["Joctã","Filho de Héber e pai dos descendentes enumerados em Gênesis 10:26-29. (Gn 10:25-29)"]],"symbols":[["Genealogias / gerações","Estrutura usada para registrar a descendência dos filhos de Noé e a formação de clãs e nações. (Gn 10:1, 32)"],["Clãs","Grupos de descendência mencionados na organização das genealogias. (Gn 10:5, 18, 20, 31-32)"],["Línguas","Categoria usada para descrever a distribuição dos povos. (Gn 10:5, 20, 31)"],["Terras e nações","Categorias usadas para registrar a distribuição dos descendentes em diferentes regiões e povos. (Gn 10:5, 20, 31-32)"],["Terras costeiras","Regiões associadas aos descendentes de Jafé. (Gn 10:5)"],["Babel e Sinear","Babel é indicada como uma das cidades do princípio do reino de Ninrode, situada na terra de Sinear. (Gn 10:10)"],["Reino de Ninrode","O texto lista Babel, Ereque, Acade e Calné como o princípio de seu reino e menciona cidades na Assíria. (Gn 10:10-12)"],["Nínive, Reobote-I, Calá e Resém","Cidades mencionadas na descrição da expansão para a Assíria. (Gn 10:11-12)"],["Sidom e Hete","Nomes apresentados como descendentes de Canaã; Sidom é identificado como seu primogênito. (Gn 10:15)"],["Território de Canaã","O texto descreve seus limites por meio de cidades e regiões, de Sidom até Gaza e em direção a Sodoma, Gomorra, Admá, Zeboim e Lasa. (Gn 10:19)"],["Pelegue e a divisão da terra","O texto associa os dias de Pelegue à divisão da terra, sem detalhar nesse versículo como ocorreu. (Gn 10:25)"],["Região de Joctã","Área descrita entre Messa, Sefar e a região montanhosa do Oriente. (Gn 10:30)"],["Depois do dilúvio","Referência temporal que situa a dispersão das nações na conclusão do capítulo. (Gn 10:32)"]]};
GENESIS_NOTES[9]={"summary":"Depois de saírem da arca, Deus abençoa Noé e seus filhos e lhes ordena que sejam fecundos e encham a terra. O capítulo registra orientações sobre os animais, o alimento e o sangue, além da declaração sobre a vida humana e a imagem de Deus. Deus estabelece uma aliança com Noé, seus descendentes e todos os seres vivos, e apresenta o arco nas nuvens como sinal dessa aliança. Na parte final, Noé planta uma vinha, bebe vinho e fica embriagado. Cam vê a nudez do pai e conta aos irmãos; Sem e Jafé cobrem Noé sem olhar para ele. Ao despertar, Noé pronuncia palavras sobre Canaã, Sem e Jafé. O capítulo termina com a idade e a morte de Noé.","explanation":"O capítulo começa com bênçãos e instruções dirigidas a Noé e seus filhos. O texto menciona a relação dos seres humanos com os animais, a permissão para comer seres que se movem e vivem, a proibição de comer carne com seu sangue e a prestação de contas pelo sangue humano. Em seguida, Deus declara a aliança com Noé, sua descendência e todos os seres vivos, afirmando que não haverá outro dilúvio para destruir toda carne. O arco nas nuvens é apresentado como sinal dessa aliança. A narrativa então passa à vida de Noé após o dilúvio: o cultivo da vinha, a embriaguez, o episódio envolvendo Cam, Sem e Jafé e as palavras pronunciadas por Noé sobre seus descendentes. O capítulo encerra com o registro dos trezentos e cinquenta anos vividos por Noé depois do dilúvio e sua idade total.","episodes":"1. Deus abençoa Noé e seus filhos e ordena que encham a terra (9:1)\n2. Declaração sobre os animais e a alimentação (9:2-3)\n3. Orientação sobre não comer carne com sangue (9:4)\n4. Declaração sobre a prestação de contas pelo sangue humano (9:5-6)\n5. Repetição da ordem de fecundidade e multiplicação (9:7)\n6. Deus anuncia a aliança com Noé, seus filhos e os seres vivos (9:8-11)\n7. O arco nas nuvens é apresentado como sinal da aliança (9:12-17)\n8. Identificação dos filhos de Noé e menção a Canaã (9:18-19)\n9. Noé planta uma vinha e se embriaga (9:20-21)\n10. Cam vê a nudez do pai e conta aos irmãos (9:22)\n11. Sem e Jafé cobrem Noé sem olhar para sua nudez (9:23)\n12. Noé pronuncia palavras sobre Canaã, Sem e Jafé (9:24-27)\n13. Idade e morte de Noé (9:28-29)","refs":"Gn 1:26-28; Gn 6:18; Gn 8:20-22; Gn 9:1-29; Gn 10:1-32; Is 54:9; Ez 14:14, 20; Mt 24:37-39; Lc 17:26-27; 1Pe 3:20; 2Pe 2:5","characters":[["Deus","Abençoa Noé e seus filhos, dá instruções sobre a vida e o sangue, estabelece a aliança e apresenta o arco como sinal. (Gn 9:1-17)"],["Noé","Recebe as palavras de Deus, planta uma vinha, bebe vinho, fica embriagado e pronuncia palavras sobre Canaã, Sem e Jafé. (Gn 9:1-29)"],["Sem","Filho de Noé; junto com Jafé, cobre a nudez do pai sem olhar para ele. (Gn 9:18, 23, 26)"],["Cam","Filho de Noé e pai de Canaã; vê a nudez do pai e conta aos dois irmãos. (Gn 9:18, 22)"],["Jafé","Filho de Noé; junto com Sem, cobre a nudez do pai. (Gn 9:18, 23, 27)"],["Canaã","Filho de Cam; é mencionado na declaração pronunciada por Noé. (Gn 9:18, 22, 25-27)"],["Descendentes de Noé","São incluídos na aliança anunciada por Deus e na ordem para se multiplicarem sobre a terra. (Gn 9:1, 8-10, 19)"],["Seres vivos","Aves, animais domésticos e animais da terra são incluídos na aliança. (Gn 9:10, 12, 15-16)"]],"symbols":[["Bênção","Deus abençoa Noé e seus filhos e lhes dirige a ordem de serem fecundos e se multiplicarem. (Gn 9:1, 7)"],["Temor dos animais","O texto declara que o temor e o medo dos seres humanos estarão sobre os animais da terra, as aves e os peixes. (Gn 9:2)"],["Alimento","Deus declara que tudo o que se move e vive servirá de alimento, assim como antes havia dado as plantas verdes. (Gn 9:3)"],["Sangue e vida","O texto proíbe comer carne com seu sangue e associa o sangue à vida. (Gn 9:4-5)"],["Imagem de Deus","A declaração sobre o ser humano feito à imagem de Deus aparece como fundamento apresentado no texto para a prestação de contas pelo sangue humano. (Gn 9:6)"],["Aliança","Compromisso estabelecido por Deus com Noé, seus descendentes e todo ser vivo, com a declaração de que não haverá outro dilúvio para destruir toda carne. (Gn 9:8-17)"],["Arco nas nuvens","Sinal da aliança entre Deus, a terra e todo ser vivo. (Gn 9:12-17)"],["Nuvens","O texto menciona a reunião de nuvens sobre a terra junto ao aparecimento do arco. (Gn 9:13-14)"],["Vinha","Plantação feita por Noé após o dilúvio. (Gn 9:20)"],["Vinho e embriaguez","Noé bebe do vinho da vinha, embriaga-se e fica descoberto dentro de sua tenda. (Gn 9:21, 24)"],["Tenda","Local em que Noé fica descoberto após se embriagar. (Gn 9:21)"],["Capa","Peça usada por Sem e Jafé para cobrir a nudez do pai. (Gn 9:23)"],["Nudez","O episódio descreve Cam vendo a nudez de Noé e Sem e Jafé cobrindo-a sem olhar. (Gn 9:22-23)"],["Servidão","Termo presente nas palavras de Noé a respeito de Canaã em relação aos irmãos. (Gn 9:25-27)"],["Tendas de Sem","Expressão que aparece na declaração de Noé sobre Jafé habitar nas tendas de Sem. (Gn 9:27)"],["Trezentos e cinquenta anos","Período que Noé viveu depois do dilúvio. (Gn 9:28)"],["Novecentos e cinquenta anos","Total dos dias de vida de Noé, segundo o registro do capítulo. (Gn 9:29)"]]};
GENESIS_NOTES[8]={"summary":"Deus lembra-se de Noé e dos seres vivos que estão com ele na arca, faz passar um vento sobre a terra e as águas começam a baixar. As fontes do abismo e as comportas dos céus são fechadas, e a chuva é detida. A arca repousa sobre os montes de Ararate. Noé envia um corvo e, em seguida, uma pomba em diferentes ocasiões; a pomba retorna primeiro sem encontrar lugar para pousar, depois traz uma folha nova de oliveira e, na terceira soltura, não retorna. O capítulo registra o secamento das águas e da terra, a ordem de Deus para sair da arca e a saída de Noé, sua família e os animais.","explanation":"O relato acompanha a diminuição das águas por etapas e registra datas específicas: o repouso da arca no sétimo mês, a aparição dos cumes dos montes no décimo mês, as solturas das aves e o secamento da superfície do solo no primeiro mês do ano seiscentos e um de Noé. A terra é declarada seca no segundo mês, dia vinte e sete. Deus então ordena que Noé e os demais saiam da arca. A ordem também determina que os animais saiam e se espalhem, sejam fecundos e se multipliquem. O capítulo termina com a saída de todos conforme suas famílias.","episodes":"1. Deus lembra-se de Noé e faz passar um vento sobre a terra (8:1)\n2. Fechamento das fontes e diminuição das águas (8:2-3)\n3. A arca repousa nos montes de Ararate (8:4)\n4. Aparecem os cumes dos montes (8:5)\n5. Noé abre a janela e solta um corvo (8:6-7)\n6. Primeira soltura da pomba e seu retorno à arca (8:8-9)\n7. Segunda soltura da pomba e retorno com uma folha de oliveira (8:10-11)\n8. Terceira soltura da pomba; ela não retorna (8:12)\n9. Secamento da superfície do solo e remoção da cobertura da arca (8:13)\n10. A terra fica seca e Deus ordena a saída (8:14-17)\n11. Noé, sua família e os animais saem da arca (8:18-19)","refs":"Gn 6:13-22; Gn 7:11-24; Gn 8:1-22; Gn 9:1-17; Is 54:9; Mt 24:37-39; Lc 17:26-27; Hb 11:7; 1Pe 3:20; 2Pe 2:5","characters":[["Deus","Lembra-se de Noé e dos seres vivos na arca, faz passar um vento sobre a terra e ordena a saída da arca. (Gn 8:1, 15-17)"],["Noé","Aguarda a diminuição das águas, envia o corvo e a pomba, observa o estado da terra e sai da arca quando recebe a ordem. (Gn 8:1-19)"],["Mulher de Noé","Sai da arca com Noé. (Gn 8:16, 18)"],["Sem","Filho de Noé; sai da arca com a família. (Gn 8:16, 18)"],["Cam","Filho de Noé; sai da arca com a família. (Gn 8:16, 18)"],["Jafé","Filho de Noé; sai da arca com a família. (Gn 8:16, 18)"],["Mulheres dos filhos de Noé","Saem da arca com Noé e seus filhos. (Gn 8:16, 18)"],["Corvo","Ave solta por Noé; sai e volta repetidamente até que as águas secam de sobre a terra. (Gn 8:7)"],["Pomba","Ave solta por Noé em três ocasiões; retorna na primeira, volta com uma folha de oliveira na segunda e não retorna na terceira. (Gn 8:8-12)"],["Animais da arca","Saem da arca segundo suas famílias, conforme a ordem dada a Noé. (Gn 8:17-19)"]],"symbols":[["Vento","Deus faz passar um vento sobre a terra, e as águas baixam. (Gn 8:1)"],["Fontes do abismo","São fechadas no processo de diminuição das águas. (Gn 8:2)"],["Comportas dos céus","São fechadas, e a chuva dos céus é detida. (Gn 8:2)"],["Cento e cinquenta dias","Período mencionado antes de as águas diminuírem, em continuidade ao registro do capítulo anterior. (Gn 7:24; 8:3)"],["Montes de Ararate","Local onde a arca repousa no sétimo mês, no dia dezessete. (Gn 8:4)"],["Janela da arca","Abertura feita por Noé, usada para soltar as aves. (Gn 8:6-8)"],["Corvo","Ave enviada por Noé para observar a condição das águas; o texto diz que ia e voltava. (Gn 8:7)"],["Pomba","Ave enviada por Noé em três ocasiões para verificar se as águas haviam diminuído. (Gn 8:8-12)"],["Folha nova de oliveira","Folha trazida pela pomba no bico, indicando no próprio relato que as águas haviam diminuído. (Gn 8:11)"],["Cobertura da arca","Noé a remove quando a superfície do solo já está seca. (Gn 8:13)"],["Datas e meses","O capítulo registra o sétimo, décimo, primeiro e segundo meses, além dos dias correspondentes, para marcar as etapas do secamento. (Gn 8:4-5, 13-14)"],["Terra seca","Condição da terra registrada antes da ordem para sair da arca. (Gn 8:13-14)"],["Famílias dos animais","O texto informa que os animais saíram da arca segundo suas famílias. (Gn 8:19)"],["Fecundidade e multiplicação","Ordem dada para que os seres vivos se espalhem e se multipliquem sobre a terra. (Gn 8:17)"]]};
function renderStudyItems(items){return '<div class="study-catalog">'+items.map(([name,description])=>'<article class="guidecard"><h4>'+esc(name)+'</h4><p>'+esc(description)+'</p></article>').join('')+'</div>';}
function studyText(items){return (items||[]).map(([name,description])=>name+' | '+description).join('\n');}
function renderStudyText(value){const items=String(value||'').split(/\r?\n/).map(line=>line.trim()).filter(Boolean).map(line=>{const p=line.split('|');return [p.shift().trim(),p.join('|').trim()||'Sem descrição adicionada.']});return items.length?renderStudyItems(items):'<span class="related-empty">Nenhum item cadastrado neste capítulo.</span>';}


const $=id=>document.getElementById(id);
const key='enciclopediaBiblicaEditsV1';
const AUTO_BACKUP_KEY='encBibAutoBackupV1';
const AUTO_BACKUP_HISTORY_KEY='encBibAutoBackupHistoryV1';
const ERROR_LOG_KEY='encBibErrorLogV1';
const BACKUP_KEYS=[key,'encBibGuides','encBibStudyEdits','encBibSymbols','encBibCharacters'];
function readLocalData(storageKey,fallback){try{const raw=localStorage.getItem(storageKey);return raw===null?fallback:JSON.parse(raw)}catch(error){return fallback}}
function saveLocalData(storageKey,value){
  localStorage.setItem(storageKey,value);
  if(BACKUP_KEYS.includes(storageKey)){
    try{
      const data={};
      BACKUP_KEYS.forEach(k=>{const saved=k===storageKey?value:localStorage.getItem(k);if(saved!==null)data[k]=saved});
      const snapshot={savedAt:new Date().toISOString(),data};
      localStorage.setItem(AUTO_BACKUP_KEY,JSON.stringify(snapshot));
      const history=readLocalData(AUTO_BACKUP_HISTORY_KEY,[]);
      history.unshift(snapshot);
      localStorage.setItem(AUTO_BACKUP_HISTORY_KEY,JSON.stringify(history.slice(0,8)));
    }catch(error){console.warn('Não foi possível atualizar o backup automático local:',error)}
  }
}
function recordAppError(message,source=''){
  try{
    const logs=readLocalData(ERROR_LOG_KEY,[]);
    logs.unshift({at:new Date().toISOString(),message:String(message||'Erro desconhecido').slice(0,500),source:String(source||'').slice(0,300)});
    localStorage.setItem(ERROR_LOG_KEY,JSON.stringify(logs.slice(0,20)));
  }catch(error){console.warn('Não foi possível registrar o erro localmente:',error)}
}
window.addEventListener('error',event=>recordAppError(event.message,event.filename));
window.addEventListener('unhandledrejection',event=>recordAppError(event.reason&&event.reason.message?event.reason.message:event.reason,'Promise rejeitada'));
(function restoreMissingLocalData(){
  try{
    let backup=JSON.parse(localStorage.getItem(AUTO_BACKUP_KEY)||'null');
    if(!backup||!backup.data){
      const history=readLocalData(AUTO_BACKUP_HISTORY_KEY,[]);
      backup=history.find(item=>item&&item.data)||null;
    }
    if(!backup||!backup.data)return;
    BACKUP_KEYS.forEach(k=>{if(localStorage.getItem(k)===null&&typeof backup.data[k]==='string')localStorage.setItem(k,backup.data[k])});
  }catch(error){console.warn('Backup automático local indisponível:',error)}
})();
let edits=readLocalData(key,{});
let currentBook=0,currentChapter=1;
const old=$('oldBooks'), neo=$('newBooks');
function renderBooks(filter=''){old.innerHTML='';neo.innerHTML='';BOOKS.forEach((b,i)=>{if(!b.name.toLowerCase().includes(filter.toLowerCase()))return;let el=document.createElement('button');el.className='book';el.setAttribute('aria-label',b.name+', '+b.chapters+' capítulos');el.innerHTML=`<span class="book-art">${window.bookArtwork?window.bookArtwork(i):''}</span><span class="book-name">${b.name}</span><small>${b.chapters} capítulos</small>`;el.onclick=()=>openBook(i);(i<39?old:neo).appendChild(el)})}
function show(view){['homeView','readerView','adminView','symbolsView','charactersView','detailView'].forEach(id=>$(id).classList.add('hidden'));$(view+'View').classList.remove('hidden');document.querySelectorAll('.navbtn').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.querySelectorAll('.bottom-tab').forEach(b=>b.classList.toggle('active',b.dataset.view===view));}
function openBook(i){currentBook=i;show('reader');renderBook()}
window.openChapterFromButton=function(chapter){
 try{
  const n=Number(chapter);
  if(!Number.isInteger(n)||n<1||n>BOOKS[currentBook].chapters)return;
  openChapter(n);
 }catch(error){
  recordAppError(error&&error.stack?error.stack:error,'Falha ao abrir capítulo '+chapter);
  const message='Erro ao abrir o capítulo '+chapter+': '+(error&&error.message?error.message:String(error));
  const reader=$('reader');
  if(reader)reader.innerHTML='<div class="readerbox"><h2>Erro ao abrir o capítulo</h2><p>'+esc(message)+'</p><button type="button" class="back" onclick="renderBook()">← Voltar à lista de capítulos</button></div>';
  alert(message);
  console.error(message,error);
 }
};

