$('editBook').onchange=fillChapters;$('editChapter').onchange=loadEdit;fillChapters();
$('saveChapter').onclick=()=>{let k=`${$('editBook').value}-${$('editChapter').value}`;edits[k]={title:$('chapterTitle').value,summary:$('chapterSummary').value,explanation:$('chapterExplanation').value,versesText:$('chapterVerses').value,episodes:$('chapterEpisodes').value,refs:$('chapterRefs').value,characterDetailsText:$('chapterCharacters').value,symbolDetailsText:$('chapterSymbols').value};persist();$('saveStatus').textContent='Capítulo salvo neste navegador e incluído no backup automático local.'};
