$('saveStudyItem').onclick=()=>{if(!studyCurrentItem){$('studyEditStatus').textContent='Abra um item da biblioteca antes de editar.';return}const name=$('studyEditName').value.trim(),category=$('studyEditCategory').value.trim(),description=$('studyEditDescription').value.trim();if(!name||!category||!description){$('studyEditStatus').textContent='Preencha nome, categoria e explicação.';return}const edits=JSON.parse(localStorage.getItem('encBibStudyEdits')||'{}');edits[studyCurrentItem._id]={name,category,description};saveLocalData('encBibStudyEdits',JSON.stringify(edits));studyCurrentItem={...studyCurrentItem,name,category,description};$('studyEditStatus').textContent='Item atualizado e incluído no backup automático local.';renderSymbols(category);};
function renderCharacters(){const items=JSON.parse(localStorage.getItem('encBibCharacters')||'[]');$('characterList').innerHTML=items.length?items.map((x,i)=>`<button class="link-card" data-character="${i}"><span>${esc(x.name)}</span><small>Ver biografia →</small></button>`).join(''):'<article class="guidecard"><p>Ainda não há personagens cadastrados. Use o Painel administrativo para adicionar o primeiro.</p></article>';document.querySelectorAll('[data-character]').forEach(b=>b.onclick=()=>openDetail('character',+b.dataset.character))}
